<?php require __DIR__.'/includes/bootstrap.php';$orderNum=(string)get('order','');$order=null;if($orderNum){$st=db()->prepare('SELECT * FROM orders WHERE order_number=? AND (customer_phone=? OR ?="")');$phone=(string)get('phone','');$st->execute([$orderNum,$phone,$phone]);$order=$st->fetch();}$title='Track Order';require __DIR__.'/includes/header.php';?><div class="max-w-3xl mx-auto px-3 sm:px-5 py-12"><div class="text-xs tracking-[.2em] text-slate-400 font-black">ORDER TRACKING</div><h1 class="text-3xl font-black mt-1">Track Your Order</h1><form class="bg-white border rounded-2xl p-5 mt-6 grid sm:grid-cols-[1fr_1fr_auto] gap-3"><input name="order" value="<?=e($orderNum)?>" placeholder="Order ID e.g. PR-260812-ABC123" class="rounded-xl border-slate-200"><input name="phone" placeholder="Phone number" class="rounded-xl border-slate-200"><button class="rounded-xl bg-slate-950 text-white px-5 font-bold">Track</button></form><?php if($order):$statuses=['pending','confirmed','processing','ready_to_ship','shipped','delivered'];$idx=array_search($order['order_status'],$statuses,true);if($idx===false)$idx=0;?><div class="bg-white border rounded-2xl p-6 mt-6"><div class="flex justify-between"><div><div class="text-slate-400 text-sm">Order</div><div class="font-black text-xl"><?=e($order['order_number'])?></div></div><div class="text-right"><div class="text-slate-400 text-sm">Total</div><div class="font-black"><?=money($order['total'])?></div></div></div><div class="mt-8 grid grid-cols-6 gap-1"><?php foreach($statuses as $i=>$s):?><div class="text-center"><div class="mx-auto w-9 h-9 rounded-full grid place-items-center <?=($i<=$idx?'bg-emerald-500 text-white':'bg-slate-100 text-slate-400')?>"><?=($i<=$idx?'✓':'')?></div><div class="text-[10px] mt-2 <?=($i<=$idx?'font-bold':'text-slate-400')?>"><?=ucwords(str_replace('_',' ',$s))?></div></div><?php endforeach;?></div></div><?php elseif($orderNum):?><div class="mt-6 p-4 rounded-xl bg-rose-50 text-rose-700">Order not found. Provide the correct order ID and phone number.</div><?php endif;?></div><?php require __DIR__.'/includes/footer.php';?>
